import { ItemBlock } from "./item-block.model";
import { RuneBlock } from "./rune-block.model";
import { SpellBlock } from "./spell-block-model";
import { SkillBlock } from "./skill-block.model";
import { StatusEffect } from "./status-effect.model";
import { CurrentEvent } from "./current-events.model";

export interface Drawing {
  path: string;
  color: string;
  lineWidth: number;
}

export interface Token {
  characterId: string;
  position: { q: number; r: number };
  image?: string;
  name: string;
}

export interface BattleMap {
  id: string;
  name: string;
  drawings: Drawing[];
  tokens: Token[];
}

export interface TrashItem {
  type: 'item' | 'rune' | 'spell' | 'skill';
  data: ItemBlock | RuneBlock | SpellBlock | SkillBlock;
  deletedAt: number; // Timestamp
}

export interface FantasyClock {
  year: number;
  day: number; // 1..360
  hour: number; // 0..23
  minute: number; // 0..59
}

export interface EncounterTimerSettings {
  enabled: boolean;
  intervalHours: number;
  nextTriggerAtHour: number;
}

export interface WorldData {
  name: string;
  /** Admin who created this world (for the homepage "your worlds" listing). */
  ownerUserId?: string;
  worldClockMinutes?: number; // Unix timestamp in minutes for synced world clock
  worldClock?: FantasyClock;
  encounterTimer?: EncounterTimerSettings;
  kampfrundeActive?: boolean;
  characterIds: string[]; // All characters in this world
  partyIds: string[]; // Characters currently in the active party
  
  // Library system - new approach
  linkedLibraries?: string[]; // IDs of linked library files
  
  // Deprecated: Direct library arrays (kept for backwards compatibility)
  itemLibrary: ItemBlock[];
  runeLibrary: RuneBlock[];
  spellLibrary: SpellBlock[];
  skillLibrary: SkillBlock[];
  statusEffectLibrary: StatusEffect[];
  
  // Current Events system - replaces battle loot
  currentEvents: CurrentEvent[];
  
  // Deprecated: Old loot system (kept for backwards compatibility)
  lootBundles: LootBundle[];
  battleLoot: LootItem[];
  
  battleParticipants: BattleParticipant[];
  battleTimeline?: BattleTimelineEntry[]; // Full tile order for lobby sync
  currentTurnIndex: number;
  trash: TrashItem[]; // Recycle bin for deleted items
  battleMaps: BattleMap[];
}

/** Serialized tile for faithful lobby sync */
export interface BattleTimelineEntry {
  id: string;
  characterId: string;
  team: string;
  turnNumber: number;
  timing: number;
  isScripted: boolean;
}

export interface LootItem {
  id: string;
  type: 'item' | 'rune' | 'spell' | 'skill' | 'currency';
  data: any; // The actual item/rune/spell/skill data
  claimedBy: string[]; // Character IDs who have claimed this
  recipientIds?: string[]; // Specific party members who should receive this loot (if empty, all party members)
}

export interface LootBundle {
  id: string;
  name: string;
  items: ItemBlock[];
  runes: RuneBlock[];
  spells: SpellBlock[];
  skills: SkillBlock[];
  currency?: {
    copper?: number;
    silver?: number;
    gold?: number;
    platinum?: number;
  };
}

export interface BattleParticipant {
  characterId: string;
  name: string;
  speed: number;
  turnFrequency: number; // Calculated based on speed
  nextTurnAt: number; // Used to determine turn order
  currentTurn?: number; // The next turn number this character will take
  portrait?: string; // Character portrait URL
  team?: string; // Team color for grouping (e.g., 'red', 'blue', 'green', 'yellow', 'purple')
  currentHealth?: number; // Current health points
  maxHealth?: number; // Maximum health points
}

export function createEmptyWorld(name: string): WorldData {
  const defaultClock: FantasyClock = {
    year: 321,
    day: 1,
    hour: 8,
    minute: 0,
  };
  const defaultAbsoluteHour = ((defaultClock.year * 360 + (defaultClock.day - 1)) * 24) + defaultClock.hour;

  return {
    name,
    worldClockMinutes: Math.floor(Date.now() / 60000),
    worldClock: defaultClock,
    encounterTimer: {
      enabled: false,
      intervalHours: 4,
      nextTriggerAtHour: defaultAbsoluteHour + 4,
    },
    characterIds: [],
    partyIds: [],
    linkedLibraries: [],
    itemLibrary: [],
    runeLibrary: [],
    spellLibrary: [],
    skillLibrary: [],
    statusEffectLibrary: [],
    currentEvents: [],
    lootBundles: [],
    battleLoot: [],
    battleParticipants: [],
    currentTurnIndex: 0,
    trash: [],
    battleMaps: [],
  };
}